function platformOf(array $s):string{$raw=strtolower(($s['name']??'').' '.($s['category']??'').' '.($s['service']??''));$map=['youtube'=>['youtube','youtu.be'],'facebook'=>['facebook','fb'],'instagram'=>['instagram','ig'],'tiktok'=>['tiktok','tik tok'],'telegram'=>['telegram','tg'],'twitter'=>['twitter',' x '],'linkedin'=>['linkedin'],'discord'=>['discord'],'spotify'=>['spotify'],'twitch'=>['twitch'],'soundcloud'=>['soundcloud']];foreach($map as $k=>$words)foreach($words as $w)if(str_contains($raw,$w))return $k;return 'other';}
function serviceTypeOf(array $s,string $platform):string{$raw=strtolower(($s['name']??'').' '.($s['category']??'').' '.($s['service']??''));$types=['followers'=>'Followers','subscribers'=>'Subscribers','views'=>'Views','likes'=>'Likes','comments'=>'Comments','shares'=>'Shares','watch time'=>'Watch Time','members'=>'Members','saves'=>'Saves','story views'=>'Story Views','reactions'=>'Reactions','engagement'=>'Engagement'];foreach($types as $n=>$l)if(str_contains($raw,$n))return $l;if($platform==='youtube'){if(str_contains($raw,'sub'))return'Subscribers';if(str_contains($raw,'view'))return'Views';if(str_contains($raw,'like'))return'Likes';}if($platform==='tiktok'){if(str_contains($raw,'sub'))return'Subscribers';if(str_contains($raw,'view'))return'Views';if(str_contains($raw,'like'))return'Likes';if(str_contains($raw,'follow'))return'Followers';}return'Other';}
