<?php if($page==='services'||$page==='dashboard'||$page==='home'): ?><div id="orderModal" style="display:none;position:fixed;inset:0;background:rgba(16,24,40,.55);z-index:100;padding:20px;overflow:auto"><div class="form-card card" style="margin:5vh auto;background:#fff"><div style="display:flex;justify-content:space-between;align-items:center"><div><h2 style="margin:0">Place Order</h2><div class="muted" id="orderLabel"></div></div><button class="btn secondary" onclick="closeOrder()">Close</button></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="order"><input type="hidden" name="service_id" id="orderSid"><input type="hidden" name="service_name" id="orderName"><input type="hidden" name="unit_price" id="orderPrice"><label>Link / Username</label><input class="input" name="link" required><label>Quantity</label><input class="input" type="number" name="quantity" id="orderQty" required oninput="calcTotal()"><div class="side-note" style="margin-top:15px;display:flex;justify-content:space-between"><span>Total</span><b id="orderTotal">৳0.00</b></div><button class="btn green" style="width:100%;margin-top:15px">Confirm Order</button></form></div></div><script>function openOrder(id,name,p,min,max){document.getElementById('orderModal').style.display='block';document.getElementById('orderSid').value=id;document.getElementById('orderName').value=name;document.getElementById('orderPrice').value=p;document.getElementById('orderLabel').textContent=name+' · ৳'+p+'/1K';let q=document.getElementById('orderQty');q.min=min;q.max=max;q.value=min;calcTotal()}function closeOrder(){document.getElementById('orderModal').style.display='none'}function calcTotal(){let q=+(document.getElementById('orderQty')?.value||0),p=+(document.getElementById('orderPrice')?.value||0);document.getElementById('orderTotal').textContent='৳'+(q*p/1000).toFixed(2)}const pp=[...document.querySelectorAll('#platforms .pill')],items=[...document.querySelectorAll('.service-item')],sub=document.getElementById('subcats'),search=document.getElementById('serviceSearch');let active='all',type='all';const sets={youtube:['Subscribers','Views','Likes','Comments','Watch Time','Other'],tiktok:['Followers','Views','Likes','Subscribers','Comments','Shares','Other'],instagram:['Followers','Likes','Views','Comments','Story Views','Saves','Other'],facebook:['Followers','Likes','Views','Comments','Shares','Reactions','Other'],telegram:['Members','Views','Reactions','Other'],twitter:['Followers','Likes','Views','Comments','Other'],linkedin:['Followers','Likes','Views','Comments','Other'],discord:['Members','Other'],spotify:['Followers','Plays','Saves','Other']};function drawSub(){if(!sub)return;sub.innerHTML='';if(active==='all')return;(sets[active]||['Other']).forEach(t=>{let b=document.createElement('button');b.className='pill '+(type===t.toLowerCase()?'active':'');b.textContent=t;b.onclick=()=>{type=t.toLowerCase();drawSub();render()};sub.appendChild(b)})}function render(){let q=(search?.value||'').toLowerCase().trim(),n=0;items.forEach(x=>{let ok=(active==='all'||x.dataset.platform===active)&&(type==='all'||x.dataset.type===type)&&x.dataset.search.includes(q);x.style.display=ok?'flex':'none';if(ok)n++})}pp.forEach(b=>b.onclick=()=>{pp.forEach(x=>x.classList.remove('active'));b.classList.add('active');active=b.dataset.p;type='all';drawSub();render()});if(search)search.oninput=render;drawSub();render();</script><style>.c-bottom{position:fixed;display:flex;bottom:0;left:0;right:0;background:rgba(255,255,255,.96);border-top:1px solid var(--line);z-index:50;justify-content:space-around;padding:7px 2px;backdrop-filter:blur(14px)}.c-bottom a{display:flex;flex-direction:column;align-items:center;gap:2px;color:#667085;font-size:21px;padding:4px 10px}.c-bottom span{font-size:10px;font-weight:800}</style><?php endif; ?></body></html>
